package org.sleepwell.app;

import org.json.*;
import java.util.*;

/** Portable measurement-only codec. Does not retain Nearby identities, authentication or pairing permission. */
final class PairMotionBackup {
    static final int MAX_LINKS=10000,MAX_ROWS=100000;
    private static final Set<String> LINK=Set.of("link","session","record_start","started","ended","local_stream","peer_stream","filter_requested","protocol","close_reason");
    private static final Set<String> PACKET=Set.of("link","seq","remote_start","remote_end","received","aligned_start","aligned_end","movement","samples","offset_ms","uncertainty_ms","quality");
    private static final Set<String> WINDOW=Set.of("link","start","time","own","own_samples","peer_seq","peer","filtered","quality","uncertainty_ms");
    static JSONObject export(Store store){try{
        Map<Long,JSONObject> sessions=new HashMap<>();for(JSONObject night:store.rows("SELECT * FROM sessions WHERE end IS NOT NULL"))sessions.put(night.getLong("id"),night);
        List<JSONObject> all=store.rows("SELECT * FROM pair_links ORDER BY started LIMIT 10001");if(all.size()>MAX_LINKS)throw new IllegalArgumentException("Paired history exceeds the portable backup limit.");JSONArray links=new JSONArray(),packets=new JSONArray(),windows=new JSONArray();long omittedActive=0,omittedOutside=0;Set<String> savedLinks=new HashSet<>();Map<String,JSONObject> linkMap=new HashMap<>();
        for(JSONObject row:all){JSONObject night=sessions.get(row.getLong("session"));if(night==null){omittedActive++;continue;}long end=night.getLong("end");if(row.getLong("started")>end||row.getLong("started")<night.getLong("start")||!row.isNull("ended")&&row.getLong("ended")>end){omittedOutside++;continue;}JSONObject copy=new JSONObject(row.toString());links.put(copy);savedLinks.add(copy.getString("link"));linkMap.put(copy.getString("link"),copy);}
        Set<String> includedPackets=new HashSet<>();List<JSONObject> packetRows=store.rows("SELECT * FROM pair_packets ORDER BY link,seq LIMIT 100001"),windowRows=store.rows("SELECT * FROM pair_windows ORDER BY link,start LIMIT 100001");if(packetRows.size()>MAX_ROWS||windowRows.size()>MAX_ROWS)throw new IllegalArgumentException("Paired history exceeds the portable backup limit.");
        for(JSONObject row:packetRows){String id=row.getString("link");if(!savedLinks.contains(id))continue;JSONObject night=sessions.get(linkMap.get(id).getLong("session"));if(row.getLong("received")>night.getLong("end")||!row.isNull("aligned_end")&&row.getLong("aligned_end")>night.getLong("end")){omittedOutside++;continue;}packets.put(row);includedPackets.add(id+":"+row.getLong("seq"));}
        for(JSONObject row:windowRows){String id=row.getString("link");if(!savedLinks.contains(id))continue;JSONObject night=sessions.get(linkMap.get(id).getLong("session"));if(row.getLong("time")>night.getLong("end")||!row.isNull("peer_seq")&&!includedPackets.contains(id+":"+row.getLong("peer_seq"))){omittedOutside++;continue;}windows.put(row);}
        JSONObject value=new JSONObject().put("pair_export_scope","ended_recordings_only").put("omitted_active",omittedActive).put("omitted_outside_record",omittedOutside).put("links",links).put("packets",packets).put("windows",windows);validate(new JSONObject().put("paired_motion",value),sessions);return value;
    }catch(JSONException invalid){throw new IllegalArgumentException("Paired history needs review before backup: "+invalid.getMessage(),invalid);}}
    static void validate(JSONObject root,Map<Long,JSONObject> sessions)throws JSONException{
        JSONObject value=root.getJSONObject("paired_motion");keys(value,Set.of("pair_export_scope","omitted_active","omitted_outside_record","links","packets","windows"));if(!text(value,"pair_export_scope").equals("ended_recordings_only")||integer(value,"omitted_active")<0||integer(value,"omitted_outside_record")<0)bad();JSONArray links=value.getJSONArray("links"),packets=value.getJSONArray("packets"),windows=value.getJSONArray("windows");if(links.length()>MAX_LINKS||packets.length()>MAX_ROWS||windows.length()>MAX_ROWS)bad();Map<String,JSONObject> map=new HashMap<>();Map<String,JSONObject> nights=new HashMap<>();
        for(int i=0;i<links.length();i++){JSONObject row=links.getJSONObject(i);String id=uuid(row,"link");long session=integer(row,"session");JSONObject night=sessions.get(session);if(map.put(id,row)!=null||night==null||night.isNull("end"))bad();link(row,night);nights.put(id,night);}

        Map<String,JSONObject> packetMap=new HashMap<>();Map<String,Long> previousSequence=new HashMap<>();Map<String,Long> previousRemote=new HashMap<>();for(int i=0;i<packets.length();i++){JSONObject row=packets.getJSONObject(i);String id=text(row,"link");JSONObject link=map.get(id);if(link==null)bad();packet(row,link,nights.get(id));long seq=integer(row,"seq"),from=integer(row,"remote_start");if(seq<=previousSequence.getOrDefault(id,0L)||from<previousRemote.getOrDefault(id,0L)||packetMap.put(id+":"+seq,row)!=null)bad();previousSequence.put(id,seq);previousRemote.put(id,integer(row,"remote_end"));}
        Map<String,Long> previousEnd=new HashMap<>();for(int i=0;i<windows.length();i++){JSONObject row=windows.getJSONObject(i);String id=text(row,"link");JSONObject link=map.get(id);if(link==null)bad();window(row,link,nights.get(id),packetMap);if(integer(row,"start")<previousEnd.getOrDefault(id,0L))bad();previousEnd.put(id,integer(row,"time"));}
    }
    static void link(JSONObject row,JSONObject night)throws JSONException{keys(row,LINK);uuid(row,"link");if(integer(row,"session")<=0||!night.optString("source").equals("tracked")||!night.optString("sensor").equals(SensorProvenance.MOTION)||integer(row,"record_start")!=integer(night,"start")||integer(row,"protocol")!=1||integer(row,"filter_requested")<0||integer(row,"filter_requested")>1)bad();uuid(row,"local_stream");uuid(row,"peer_stream");bounds(integer(row,"started"),integer(row,"started"),night);if(!row.isNull("ended")){bounds(integer(row,"started"),integer(row,"ended"),night);if(!PairMotionTables.CLOSE.contains(text(row,"close_reason")))bad();}else if(!text(row,"close_reason").isEmpty())bad();}
    static void packet(JSONObject row,JSONObject link,JSONObject night)throws JSONException{
        keys(row,PACKET);if(!text(row,"link").equals(text(link,"link"))||integer(row,"seq")<=0)bad();long from=integer(row,"remote_start"),to=integer(row,"remote_end"),received=integer(row,"received");if(from<0||to<=from||to-from>15000)bad();bounds(received,received,night);if(received<integer(link,"started")||!link.isNull("ended")&&received>integer(link,"ended"))bad();measurement(row,"movement","samples");String quality=text(row,"quality");if(!PairMotionTables.PACKET_QUALITY.contains(quality))bad();boolean aligned=!row.isNull("aligned_start");if(aligned!=!row.isNull("aligned_end")||aligned!=!row.isNull("offset_ms")||aligned!=!row.isNull("uncertainty_ms"))bad();if(aligned){long a=integer(row,"aligned_start"),b=integer(row,"aligned_end"),uncertainty=integer(row,"uncertainty_ms");bounds(a,b,night);if(b<=a||b-a!=to-from||uncertainty<0||uncertainty>1000||Math.abs(integer(row,"offset_ms"))>365L*86400000||a<integer(link,"started")-15000||b>received+1000||received-b>15000||quality.equals("UNALIGNED"))bad();if(quality.equals("ALIGNED")&&(uncertainty>250||received-b>5000||row.isNull("movement")))bad();}else if(!quality.equals("UNALIGNED"))bad();if(quality.equals("MISSING")&&!row.isNull("movement"))bad();
    }
    static void window(JSONObject row,JSONObject link,JSONObject night,Map<String,JSONObject> packets)throws JSONException{
        keys(row,WINDOW);if(!text(row,"link").equals(text(link,"link")))bad();long from=integer(row,"start"),to=integer(row,"time");bounds(from,to,night);if(to<=from||to-from>15000||from<integer(link,"started")||!link.isNull("ended")&&to>integer(link,"ended"))bad();measurement(row,"own","own_samples");String quality=text(row,"quality");if(!PairMotionTables.WINDOW_QUALITY.contains(quality))bad();boolean paired=!row.isNull("peer_seq");if(paired!=!row.isNull("peer")||paired!=!row.isNull("uncertainty_ms"))bad();if(paired){if(!Set.of("FRESH_RAW","COMMON_REDUCED").contains(quality))bad();long seq=integer(row,"peer_seq"),uncertainty=integer(row,"uncertainty_ms");if(seq<=0||uncertainty<0||uncertainty>250||number(row,"peer")<0||number(row,"peer")>1000||row.isNull("own"))bad();if(packets!=null){JSONObject peer=packets.get(text(row,"link")+":"+seq);if(peer==null||!text(peer,"quality").equals("ALIGNED")||number(peer,"movement")!=number(row,"peer")||integer(peer,"aligned_start")>=to||integer(peer,"aligned_end")<=from||integer(peer,"uncertainty_ms")!=uncertainty)bad();}}else if(Set.of("FRESH_RAW","COMMON_REDUCED").contains(quality))bad();if(row.isNull("own")!=quality.equals("LOW_COVERAGE"))bad();if(!row.isNull("filtered")){double own=number(row,"own"),filtered=number(row,"filtered");if(integer(link,"filter_requested")!=1||!paired||!quality.equals("COMMON_REDUCED")||filtered<own*.5-1e-9||filtered>own)bad();}else if(quality.equals("COMMON_REDUCED"))bad();
    }
    static void restore(Store store,JSONObject value,Runnable guard)throws JSONException{for(String part:new String[]{"links","packets","windows"}){JSONArray rows=value.getJSONArray(part);for(int i=0;i<rows.length();i++){guard.run();store.getWritableDatabase().insertOrThrow("pair_"+part,null,PairMotionTables.values(rows.getJSONObject(i)));}}}
    private static void bounds(long from,long to,JSONObject night)throws JSONException{long start=integer(night,"start"),end=night.isNull("end")?start+36*3600000L:integer(night,"end");if(from<start||to<from||to>end||to-start>36*3600000L)bad();}
    private static void measurement(JSONObject row,String field,String count)throws JSONException{long samples=integer(row,count);if(samples<0||samples>1000||row.isNull(field)!=(samples==0))bad();if(!row.isNull(field)&&(number(row,field)<0||number(row,field)>1000))bad();}
    private static String uuid(JSONObject row,String key)throws JSONException{String text=text(row,key);try{if(!UUID.fromString(text).toString().equals(text))bad();}catch(IllegalArgumentException invalid){bad();}return text;}
    private static void keys(JSONObject row,Set<String> expected)throws JSONException{if(row.length()!=expected.size())bad();for(Iterator<String> keys=row.keys();keys.hasNext();)if(!expected.contains(keys.next()))bad();}
    private static long integer(JSONObject row,String key)throws JSONException{return SensorProvenance.whole(row,key);}private static double number(JSONObject row,String key)throws JSONException{return SensorProvenance.number(row,key);}private static String text(JSONObject row,String key)throws JSONException{return SensorProvenance.text(row,key);}private static void bad()throws JSONException{throw new JSONException("Invalid paired movement metadata");}
    private PairMotionBackup(){}
}
